def arch(x,y,w,h,variant):
    z=[]
    z.append(r'\begin{scope}[shift={('+str(x)+','+str(y)+')} ]')
    z.append(r'\draw[yellow!60!green,line width=1.7pt] (0,'+str(h)+') .. controls (0,0) and ('+str(w)+',0) .. ('+str(w)+','+str(h)+');')
    pts=[(0,h),(w*.13,h*.35),(w*.86,h*.35),(w,h)]
    for a,b in pts:z.append(f'\\fill[green!30!black] ({a},{b}) circle(5);')
    for a,b in [(w*.07,h*.49),(w*.91,h*.51)]:z.append(f'\\fill[yellow!60!green] ({a},{b}) circle(9);')
    if variant in (1,3):z.append(f'\\fill[yellow!60!green] ({w*.53},{h*.25}) circle(8);')
    if variant==0:
        z.append(f'\\draw[yellow!60!green,line width=1.6pt] (18,{h+8})--({w-12},{h+8});')
        z.append(f'\\draw[dashed] (4,{h-7})--({w*.13},{h*.35})--({w*.86},{h*.35})--({w-3},{h-7});')
    else:z.append(f'\\draw[gray] ({w*.22},{h*.38})..controls({w*.52},{h*.47})and({w*.64},{h*.43})..({w*.83},{h*.46});')
    def brace(path,label,at):
        z.append('\\draw '+path+';');z.append(f'\\node at {at} {{$'+label+'$};')
    if variant%2==0:
        brace(f'(10,{h*.26}) .. controls(15,{h*.02})and({w*.45},{h*.13})..({w*.52},0) .. controls({w*.55},{h*.13})and({w+10},0)..({w+12},{h*.24})','-1',f'({w*.54},-28)')
    else:
        brace(f'(8,{h*.3}) .. controls(50,{h*.16})and(28,{h*.05})..(48,{h*.08}) .. controls({w*.22},{h*.13})and({w*.32},0)..({w*.47},0)','-1',f'({w*.21},-12)')
        brace(f'({w*.57},0) .. controls({w*.66},-6)and({w*.68},{h*.1})..({w*.77},{h*.09}) .. controls({w*.86},{h*.08})and({w+22},{h*.25})..({w+10},{h*.45})',"-1",f'({w*.91},-12)')
    brace(f'(0,{h+25}) .. controls({w*.25},{h+50})and({w*.44},{h+40})..({w*.49},{h+54}) .. controls({w*.53},{h+38})and({w*.81},{h+55})..({w},{h+31})','-1',f'({w*.53},{h+84})')
    lab='+1' if variant<2 else r'\varepsilon'
    brace(f'(-10,{h*.4}) .. controls(-32,{h*.5})and(-12,{h*.61})..(-31,{h*.72}) .. controls(-18,{h*.79})and(-36,{h*.9})..(-19,{h})',lab,f'(-46,{h*.73})')
    brace(f'({w+13},{h*.4}) .. controls({w+37},{h*.48})and({w+10},{h*.63})..({w+29},{h*.73}) .. controls({w+16},{h*.79})and({w+33},{h*.93})..({w+14},{h})',lab,f'({w+48},{h*.74})')
    if variant==0:
        z.append(f'\\node at ({w*.49},{h*.39}) {{$+1$}};\\node at ({w*.19},{h*.65}) {{$+1$}};\\node at ({w*.83},{h*.66}) {{$+1$}};\\node at ({w*.49},{h*.94}) {{$-1$}};')
    else:
        brace(f'({w*.21},{h*.43}) .. controls({w*.22},{h*.49})and({w*.46},{h*.45})..({w*.48},{h*.52}) .. controls({w*.53},{h*.47})and({w*.72},{h*.53})..({w*.85},{h*.52})','+1',f'({w*.53},{h*.62})')
        brace(f'({w*.15},{h*.91}) .. controls({w*.28},{h*.85})and({w*.44},{h*.94})..({w*.5},{h*.87}) .. controls({w*.53},{h*.97})and({w*.83},{h*.89})..({w*.85},{h*.98})','+1',f'({w*.53},{h*.82})')
        z.append(f'\\node at ({w*.17},{h*.65}) {{$'+lab+'$};')
        z.append(f'\\node at ({w*.83},{h*.66}) {{$'+lab+'$};')
    if variant>=2:
        for i in range(8):z.append(f'\\draw[gray] ({w*.32+i*5},{h*.4+9})--({w*.52+i*5},{h*.35});')
    z.append(r'\end{scope}')
    return '\n'.join(z)
